         ('Какая схема посадки лука под зиму?', '5-7 сантиметров между луковичками для мелкой овсюжки, 8-10 для первой фракции, 15-20 сантиметров между рядами.'),
         ('Какой севок брать для подзимней посадки?', 'Самый мелкий, до 1 сантиметра — овсюжку, или первую фракцию до 1,5 сантиметра. Крупный весной уходит в стрелку.'),
